def __hash__(self):  # Factors
    keys = tuple(ordered(self.factors.keys()))
    values = [self.factors[k] for k in keys]
    return hash((keys, values))

def __repr__(self):  # Factors
    return "Factors({%s})" % ', '.join(
        ['%s: %s' % (k, v) for k, v in ordered(self.factors.items())])

@property
def is_zero(self):  # Factors
    """
    >>> from sympy.core.exprtools import Factors
    >>> Factors(0).is_zero
    True
    """
    f = self.factors
    return len(f) == 1 and S.Zero in f

@property
def is_one(self):  # Factors
    """
    >>> from sympy.core.exprtools import Factors
    >>> Factors(1).is_one
    True
    """
    return not self.factors

def as_expr(self):  # Factors
    """Return the underlying expression.

    Examples
    ========

    >>> from sympy.core.exprtools import Factors
    >>> from sympy.abc import x, y
    >>> Factors((x*y**2).as_powers_dict()).as_expr()
    x*y**2

    """

    args = []
    for factor, exp in self.factors.items():
        if exp != 1:
            b, e = factor.as_base_exp()
            if isinstance(exp, int):
                e = _keep_coeff(Integer(exp), e)
            elif isinstance(exp, Rational):
                e = _keep_coeff(exp, e)
            else:
                e *= exp
            args.append(b**e)
        else:
            args.append(factor)
    return Mul(*args)

def mul(self, other):  # Factors
    """Return Factors of ``self * other``.

    See Also
    ========
    div

    """
    if not isinstance(other, Factors):
        other = Factors(other)
        if other.is_zero:
            return (Factors(), Factors(S.Zero))
        if self.is_zero:
            return (Factors(S.Zero), Factors())

    self_factors = dict(self.factors)
    other_factors = dict(other.factors)

    for factor, self_exp in self.factors.items():
        try:
            other_exp = other.factors[factor]
        except KeyError:
            continue

        exp = self_exp - other_exp

        if not exp:
            del self_factors[factor]
            del other_factors[factor]
        elif _isnumber(exp):
            if exp > 0:
                self_factors[factor] = exp
                del other_factors[factor]
            else:
                del self_factors[factor]
                other_factors[factor] = -exp
        else:
            r = self_exp.extract_additively(other_exp)
            if r is not None:
                if r:
                    self_factors[factor] = r
                    del other_factors[factor]
                else:  # should be handled already
                    del self_factors[factor]
                    del other_factors[factor]
            else:
                sc, sa = self_exp.as_coeff_Add()
                if sc:
                    oc, oa = other_exp.as_coeff_Add()
                    diff = sc - oc
                    if diff > 0:
                        self_factors[factor] -= oc
                        other_exp = oa
                    elif diff < 0:
                        self_factors[factor] -= sc
                        other_factors[factor] -= sc
                        other_exp = oa - diff
                    else:
                        self_factors[factor] = sa
                        other_exp = oa
                if other_exp:
                    other_factors[factor] = other_exp
                else:
                    del other_factors[factor]

    return Factors(self_factors), Factors(other_factors)

